public java.util.Map<OrderStatus, Long> countByStatus() {
  var counts = new java.util.EnumMap<OrderStatus, Long>(OrderStatus.class);
  jdbc.query("SELECT status, COUNT(*) AS n FROM orders GROUP BY status",
      rs -> { counts.put(OrderStatus.valueOf(rs.getString("status")), rs.getLong("n")); });
  return counts;
}

